const input = $json.body || $json;
const jaar = parseInt(input.jaar) || 2026;
const periode = input.periode || 'Q1 (Jan-Mrt)';
const maanden = {'Januari':1,'Februari':2,'Maart':3,'April':4,'Mei':5,'Juni':6,'Juli':7,'Augustus':8,'September':9,'Oktober':10,'November':11,'December':12};
let kwartaal_nr=0,maand_nr=0,periode_label='';
if(periode.startsWith('Q1')){kwartaal_nr=1;periode_label=`Q1 Jan-Mrt ${jaar}`;}
else if(periode.startsWith('Q2')){kwartaal_nr=2;periode_label=`Q2 Apr-Jun ${jaar}`;}
else if(periode.startsWith('Q3')){kwartaal_nr=3;periode_label=`Q3 Jul-Sep ${jaar}`;}
else if(periode.startsWith('Q4')){kwartaal_nr=4;periode_label=`Q4 Okt-Dec ${jaar}`;}
else if(periode==='Heel jaar'){periode_label=`Heel jaar ${jaar}`;}
else if(maanden[periode]){maand_nr=maanden[periode];periode_label=`${periode} ${jaar}`;}
else{periode_label=`${periode} ${jaar}`;}
return [{json:{jaar,kwartaal_nr,maand_nr,periode_label}}];

const parse = $node['Code: Parse Periode'].json;
const omzetRijen = $input.all().filter(i => i.json.code !== '__geen__');
const omzetRows = omzetRijen.map(i => ({
  code: i.json.code || '8000',
  naam: i.json.naam || 'Omzet NL',
  aantal: parseInt(i.json.aantal || 0),
  totaal_excl: parseFloat(i.json.totaal_excl || 0),
  totaal_btw:  parseFloat(i.json.totaal_btw  || 0),
  totaal_incl: parseFloat(i.json.totaal_incl || 0),
}));
return [{ json: { ...parse, _omzetRows: omzetRows } }];

function fmt(v){return '€ '+parseFloat(v||0).toLocaleString('nl-NL',{minimumFractionDigits:2,maximumFractionDigits:2});}
const parse = $node["Code: Parse Periode"].json;
const omzetRows = $node["Code: Merge2"].json._omzetRows || [];
const kostenItems = $input.all().filter(i => i.json.code !== '__geen__');

// Omzet berekeningen
let tOmzetExcl=0, tOmzetBtw=0, tOmzetIncl=0;
for(const r of omzetRows){
  tOmzetExcl+=parseFloat(r.totaal_excl||0);
  tOmzetBtw+=parseFloat(r.totaal_btw||0);
  tOmzetIncl+=parseFloat(r.totaal_incl||0);
}

// Kosten berekeningen
let tKostenExcl=0, tKostenBtw=0, tKostenIncl=0;
const kostenSlots=[];
for(const item of kostenItems){
  const d=item.json;
  tKostenExcl+=parseFloat(d.totaal_excl||0);
  tKostenBtw+=parseFloat(d.totaal_btw||0);
  tKostenIncl+=parseFloat(d.totaal_incl||0);
  kostenSlots.push(`${d.code} ${d.naam} — ${fmt(d.totaal_excl)} (${d.aantal}x)`);
}
const resultaat = tOmzetExcl - tKostenExcl;

// Slots opbouwen: omzet → scheidingslijn → kosten
const slots=[];
for(const r of omzetRows){
  slots.push(`${r.code} ${r.naam} — ${fmt(r.totaal_excl)} (${r.aantal} facturen)`);
}
if(slots.length===0) slots.push('Geen omzet in deze periode');
slots.push('── Kosten ─────────────────────────────────');
kostenSlots.forEach(s=>slots.push(s));
if(kostenSlots.length===0) slots.push('Geen kosten in deze periode');
while(slots.length<10) slots.push('');

return [{json:{
  periode_label: parse.periode_label,
  jaar: parse.jaar, kwartaal_nr: parse.kwartaal_nr, maand_nr: parse.maand_nr,
  slot1:slots[0],slot2:slots[1],slot3:slots[2],slot4:slots[3],slot5:slots[4],
  slot6:slots[5],slot7:slots[6],slot8:slots[7],slot9:slots[8],slot10:slots[9],
  totaal_excl:  fmt(tOmzetExcl),   // = Totaal Omzet excl BTW
  totaal_btw:   fmt(tKostenExcl),  // = Totaal Kosten excl BTW
  totaal_incl:  resultaat>=0 ? fmt(resultaat)+' winst' : fmt(Math.abs(resultaat))+' verlies',
  _tOmzetExcl:tOmzetExcl,_tOmzetBtw:tOmzetBtw,_tOmzetIncl:tOmzetIncl,
  _tKostenExcl:tKostenExcl,_tKostenBtw:tKostenBtw,_tKostenIncl:tKostenIncl,
  _resultaat:resultaat,
  _omzetRows:omzetRows, _kostenRows:kostenItems.map(i=>i.json)
}}];

